(()=>{'use strict';const form=document.querySelector('#quote-form');if(!form)return;form.hidden=false;
const tr=window.wavingTranslate||(s=>s),fr=document.documentElement.lang==='fr-CA';
const content=document.querySelector('#step-content'),prev=document.querySelector('#previous'),next=document.querySelector('#next'),error=document.querySelector('#form-error');
const needs=['Buy Flags','Custom Flags','Buy Flagpole','Flagpole Installation','Flag Rental','Flagpole Rental','Flagpole Repair','Flag Replacement','Commercial Flag Service','Multi-Location Program','Other'];
const states=['YOUR REQUEST','PROJECT REQUIREMENTS','LOCATION','FILES','CONTACT','REVIEW & SEND'];
const provinces=['Ontario','Quebec','British Columbia','Alberta','Manitoba','Saskatchewan','Nova Scotia','New Brunswick','Newfoundland and Labrador','Prince Edward Island','Yukon','Northwest Territories','Nunavut'];
let step=0,busy=false,files=[],started=Date.now(),data={};const params=new URLSearchParams(location.search);if(needs.includes(params.get('need')))data.need=params.get('need');if(params.get('city'))data.city=params.get('city');if(params.get('topic'))data.topic=params.get('topic').slice(0,160);
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function event(name,extra={}){window.dispatchEvent(new CustomEvent('waving:analytics',{detail:{event:name,step:step+1,...extra}}));}event('quote_start');
function field(name,label,type='text',required=false,options=[],hint=''){let control;if(type==='select')control=`<select id="q-${name}" name="${name}" ${required?'required':''}><option value="">${tr('Choose an option')}</option>${options.map(o=>`<option value="${e(o)}" ${data[name]===o?'selected':''}>${e(tr(o))}</option>`).join('')}</select>`;else if(type==='textarea')control=`<textarea id="q-${name}" name="${name}" maxlength="4000" ${required?'required':''}>${e(data[name])}</textarea>`;else control=`<input id="q-${name}" name="${name}" type="${type}" value="${e(data[name])}" ${required?'required':''} ${type==='number'?'min="1" max="100000" step="1"':''} ${type==='text'?'maxlength="200"':''} ${name==='email'?'autocomplete="email"':name==='name'?'autocomplete="name"':name==='phone'?'autocomplete="tel"':name==='company'?'autocomplete="organization"':name==='postal'?'autocomplete="postal-code"':name==='city'?'autocomplete="address-level2"':''}>`;return `<label class="field" for="q-${name}"><span>${tr(label)}${required?' *':tr(' (optional)')}</span>${control}${hint?`<small>${tr(hint)}</small>`:''}</label>`}
function yes(name,label){return field(name,label,'select',false,['Yes','No','Not sure yet'])}
function fieldsForNeed(){let n=data.need||'',out='';if(['Buy Flags','Custom Flags','Flag Rental','Flag Replacement'].includes(n)){out+=field('flagType','Flag type','select',false,['Canadian','Provincial / territorial','International','Corporate / custom','Municipal','Indigenous','Event / promotional','Sports','Multiple types','Not sure yet']);out+=field('quantity','Number of flags','number');out+=field('dimensions','Flag dimensions', 'text',false,[],'Include units if known.');}if(n==='Custom Flags')out+=yes('artwork','Do you have artwork?');if(['Buy Flagpole','Flagpole Installation','Flagpole Rental','Flagpole Repair','Commercial Flag Service','Multi-Location Program'].includes(n)){out+=field('poles','Number of flagpoles','number');out+=field('height','Approximate pole height','text',false,[],'A ground-level estimate is enough. Do not climb or measure at height.');out+=yes('existingPole','Is there an existing flagpole?');}if(n==='Flagpole Repair')out+=field('issue','What needs attention?','select',true,['Broken or worn rope','Flag cannot be raised or lowered','Pulley / truck assembly','Clips / cleat / finial','Visible pole damage','Other / not sure']);if(['Flag Rental','Flagpole Rental'].includes(n)){out+=field('rentalStart','Rental start date','date',true);out+=field('rentalEnd','Rental end date','date',true);out+=field('eventDate','Event date','date');out+=field('setting','Indoor or outdoor?','select',true,['Indoor','Outdoor','Both']);out+=yes('rentalPoles','Do you need flagpoles?');out+=yes('installation','Do you need installation?');out+=yes('delivery','Do you need delivery?');}else if(['Buy Flagpole','Flagpole Installation','Buy Flags','Custom Flags'].includes(n)){out+=yes('installation','Do you need installation?');out+=field('setting','Indoor or outdoor?','select',false,['Indoor','Outdoor','Both']);}if(['Commercial Flag Service','Multi-Location Program'].includes(n)){out+=field('locations','Number of locations','number');out+=field('frequency','Preferred service plan','select',false,['One-time','Seasonal','Quarterly','Custom multi-site program','Not sure yet']);}if(!['Flag Rental','Flagpole Rental'].includes(n))out+=field('requiredDate','Preferred date','date');if(n==='Other')out+=field('otherNeed','What do you need?','textarea',!data.topic);return out}
function save(){content.querySelectorAll('input,select,textarea').forEach(el=>{if(el.type==='file')return;if(el.type==='radio'){if(el.checked)data[el.name]=el.value}else if(el.type==='checkbox')data[el.name]=el.checked;else data[el.name]=el.value})}
function showError(message,focus){error.textContent=tr(message);error.hidden=false;if(focus){focus.setAttribute('aria-invalid','true');focus.focus();}event('quote_validation_error')}
function valid(){save();error.hidden=true;content.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));if(step===0&&!data.need){showError('Choose what you need to continue.',content.querySelector('input'));return false}for(const el of content.querySelectorAll('input,select,textarea')){if(el.type==='file')continue;if((el.required&&typeof el.value==='string'&&!el.value.trim())||!el.checkValidity()){const label=el.closest('label')?.querySelector('span')?.textContent?.replace(' *','')||'this field';showError(el.validity.valueMissing?`Please complete ${label.toLowerCase()}.`:`Please check ${label.toLowerCase()}.`,el);return false}}if(step===1&&data.rentalStart&&data.rentalEnd&&data.rentalEnd<data.rentalStart){showError('The rental end date must be on or after the start date.',content.querySelector('[name=rentalEnd]'));return false}if(step===1&&data.eventDate&&data.rentalStart&&(data.eventDate<data.rentalStart||data.eventDate>data.rentalEnd)){showError('The event date must fall within the rental period.',content.querySelector('[name=eventDate]'));return false}if(step===2&&data.postal&&!/^[ABCEGHJ-NPRSTVXY]\d[ABCEGHJ-NPRSTV-Z][ -]?\d[ABCEGHJ-NPRSTV-Z]\d$/i.test(data.postal.trim())){showError('Enter a Canadian postal code such as M5V 2T6, or leave it blank.',content.querySelector('[name=postal]'));return false}if(step===4&&data.preferred==='Phone'&&!data.phone){showError('Add a phone number or choose email as your preferred contact method.',content.querySelector('[name=phone]'));return false}return true}
function render(){error.hidden=true;document.querySelector('#step-label').textContent=fr?`ÉTAPE ${step+1} SUR 6`:`STEP ${step+1} OF 6`;document.querySelector('#step-name').textContent=tr(states[step]);document.querySelector('#quote-progress').value=step+1;prev.hidden=step===0;next.textContent=tr(step===5?'REQUEST MY QUOTE':'CONTINUE');let out='';if(step===0)out='<h2 tabindex="-1">What do you need?</h2><p class="notice">Choose the main reason for your request. You can add other requirements later.</p><div class="need-grid">'+needs.map(n=>`<label class="need-option"><input type="radio" name="need" value="${e(n)}" ${data.need===n?'checked':''}><span>${e(tr(n))}</span></label>`).join('')+'</div>';if(step===0&&data.topic)out+='<p class="notice">'+tr('Project focus:')+' '+e(tr(data.topic))+'</p>';if(step===1)out='<h2 tabindex="-1">A little about the project.</h2><p class="notice">Share what you know. Fields marked * are required.</p><div class="form-grid">'+fieldsForNeed()+'</div>';if(step===2)out='<h2 tabindex="-1">Where do you need it?</h2><p class="notice">City and province are enough to start. On-site availability is confirmed for your request.</p><div class="form-grid">'+field('city','City or community','text',true)+field('province','Province or territory','select',true,provinces)+field('postal','Postal code')+field('address','Street address')+'</div>';if(step===3)out='<h2 tabindex="-1">Show us the details.</h2><p class="notice">Optional photos, artwork or references help explain your request. Only take photos from a safe position.</p><label class="field"><span>Choose files (optional)</span><input type="file" id="files" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.svg,.ai,.eps"><small>Up to 5 files. Maximum 10 MB per file and 20 MB total. JPG, PNG, WebP, PDF, SVG, AI or EPS. Do not include confidential documents.</small></label><ul id="file-list" class="file-list"></ul>';if(step===4)out='<h2 tabindex="-1">How can we reach you?</h2><p class="notice">Fields marked * are required. Phone is needed only if you prefer a call.</p><div class="form-grid">'+field('name','Name','text',true)+field('company','Company or organization')+field('email','Email','email',true)+field('phone','Phone','tel')+field('preferred','Preferred contact method','select',true,['Email','Phone'])+'</div>';if(step===5){const rows=[['Request',tr(data.need)],['Location',[data.city,tr(data.province),data.postal].filter(Boolean).join(', ')],['Contact',data.name],['Email',data.email],['Phone',data.phone],['Files',files.map(f=>f.name).join(', ')||tr('None')],['Rental dates',data.rentalStart?data.rentalStart+(fr?' au ':' to ')+data.rentalEnd:''],['Preferred contact',tr(data.preferred)],...Object.entries(data).filter(([k,v])=>v&&!['need','city','province','postal','name','email','phone','preferred','notes','consent','rentalStart','rentalEnd'].includes(k)).map(([k,v])=>[({flagType:'Flag type',quantity:'Quantity',dimensions:'Dimensions',poles:'Flagpoles',height:'Pole height',existingPole:'Existing pole',rentalPoles:'Poles required',eventDate:'Event date',setting:'Setting',installation:'Installation',delivery:'Delivery',requiredDate:'Preferred date',frequency:'Service plan',locations:'Locations',issue:'Repair issue',address:'Street address',company:'Company',artwork:'Artwork',otherNeed:'Other requirements',topic:'Project focus'})[k]||k,['flagType','existingPole','rentalPoles','setting','installation','delivery','frequency','issue','artwork','topic'].includes(k)?tr(v):v])];out='<h2 tabindex="-1">Anything else? Then review.</h2>'+field('notes','Project details','textarea',false,[],'Include deadlines, access requirements or additional services. Avoid sensitive personal information.')+'<dl class="review-list">'+rows.filter(r=>r[1]).map(([k,v])=>`<dt>${e(tr(k))}</dt><dd data-i18n-skip>${e(v)}</dd>`).join('')+'</dl><p class="notice">Use BACK to change your details. A quote request does not place an order or reserve a date.</p><label class="consent"><input type="checkbox" name="consent" required '+(data.consent?'checked':'')+'><span>I agree to be contacted about this request and have read the <a href="/privacy/" target="_blank" rel="noopener">privacy information</a>. This is not marketing consent. *</span></label>'}content.innerHTML=out;window.wavingLocalize?.(content);if(step===3){drawFiles();document.querySelector('#files').addEventListener('change',addFiles)}event('quote_step_view')}
function drawFiles(){const list=document.querySelector('#file-list');list.replaceChildren();files.forEach((f,i)=>{const li=document.createElement('li');li.textContent=`${f.name} (${(f.size/1048576).toFixed(1)} ${fr?'Mo':'MB'}) `;const b=document.createElement('button');b.type='button';b.textContent=tr('REMOVE');b.setAttribute('aria-label',(fr?'Retirer ':'Remove ')+f.name);b.addEventListener('click',()=>{files.splice(i,1);drawFiles()});li.append(b);list.append(li)})}
function addFiles(ev){const selected=[...ev.target.files];let merged=[...files];for(const f of selected){if(!/\.(jpe?g|png|webp|pdf|svg|ai|eps)$/i.test(f.name)){showError('That file type is not supported. Choose an image, PDF or supported artwork file.');ev.target.value='';return}if(f.size>10*1048576){showError('Each file must be 10 MB or smaller.');ev.target.value='';return}if(!merged.some(x=>x.name===f.name&&x.size===f.size))merged.push(f)}if(merged.length>5||merged.reduce((a,f)=>a+f.size,0)>20*1048576){showError('Choose up to five files with a combined size of 20 MB or less.');ev.target.value='';return}files=merged;error.hidden=true;drawFiles();ev.target.value=''}
prev.addEventListener('click',()=>{if(busy)return;save();step--;render();content.querySelector('h2').focus()});next.addEventListener('click',async()=>{if(busy||!valid())return;if(step<5){step++;render();content.querySelector('h2').focus();return}await submit()});form.addEventListener('submit',ev=>{ev.preventDefault();next.click()});content.addEventListener('change',ev=>{if(ev.target.name==='need'&&data.need!==ev.target.value){const keep=['city','province','postal','address','name','company','email','phone','preferred','notes','consent','topic'];data=Object.fromEntries(Object.entries(data).filter(([k])=>keep.includes(k)));data.need=ev.target.value}});
async function submit(){const cfg=window.WAVING_CONFIG||{};if(!cfg.quoteEndpoint){showError('Your request could not be sent right now. Your entries are still here. Please call (833) 696-9996 to discuss your quote.');event('quote_submit_unavailable');return}if(form.elements._gotcha.value||Date.now()-started<3000){showError('Please review your request and try again.');return}busy=true;next.disabled=true;prev.disabled=true;next.textContent=tr('SENDING…');form.setAttribute('aria-busy','true');const payload=new FormData();for(const [k,v]of Object.entries(data))if(v!==''&&v!==false)payload.append(k,String(v));files.forEach(f=>payload.append('attachment',f,f.name));payload.append('_subject','Waving quote request — '+data.need);payload.append('_gotcha','');payload.append('language',document.documentElement.lang);const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);try{const r=await fetch(cfg.quoteEndpoint,{method:'POST',body:payload,headers:{Accept:'application/json'},signal:controller.signal});let result={};try{result=await r.json()}catch{throw new Error('Invalid response')}if(!r.ok||result.ok!==true||result.errors)throw new Error('Not accepted');form.hidden=true;const success=document.querySelector('#quote-success');success.hidden=false;success.setAttribute('tabindex','-1');success.focus();event('quote_submit_accepted')}catch(err){showError('We could not confirm that your request was accepted. Your entries are still here. Please try again later or call (833) 696-9996.');event('quote_submit_error')}finally{clearTimeout(timer);busy=false;next.disabled=false;prev.disabled=false;next.textContent=tr('REQUEST MY QUOTE');form.removeAttribute('aria-busy')}}
render();})();
